            for key, value in responses.items():
                writer.writerow((key, value.get("status"), value.get("seconds"), value.get("gpu_after", {}).get("peak_allocated_mib", "")))
            writer.writerow(("parallel_wall", status, round(wall_seconds, 4), ""))
