const patch = "*** Begin Patch
*** Update File: /tmp/diag_shadow_edges.py
@@
 def metrics(image: np.ndarray, mask: np.ndarray) -> dict:
@@
-    output = {}
+    lab = cv2.cvtColor(image, cv2.COLOR_BGR2LAB).astype(np.float32)
+    valid_lab = lab[valid]
+    low_cut, high_cut = np.percentile(valid_lab[:, 0], (20, 80))
+    low = valid & (lab[:, :, 0] <= low_cut)
+    high = valid & (lab[:, :, 0] >= high_cut)
+    low_ab = np.mean(lab[low, 1:3], axis=0)
+    high_ab = np.mean(lab[high, 1:3], axis=0)
+    output = {
+        "bright_dark_ab_delta": float(np.linalg.norm(high_ab - low_ab)),
+        "bright_dark_a_delta": float(abs(high_ab[0] - low_ab[0])),
+        "bright_dark_b_delta": float(abs(high_ab[1] - low_ab[1])),
+    }
*** End Patch";
text(await tools.apply_patch(patch));

