from __future__ import annotations

import json
from copy import deepcopy
from collections import Counter
from pathlib import Path
from typing import Any, Iterable

import numpy as np

from src.scoring_bridge.fitting import (
    GRADE_THRESHOLDS,
    apply_isotonic,
    fit_isotonic,
    mapping_diagnostics,
)
from src.scoring_bridge.legacy_scoring import (
    legacy_dimension_scores_from_features,
    prepare_references,
)
from src.scoring_bridge.manifest import DIMENSION_IDS


def load_latest_observations(
    paths: Iterable[Path],
) -> tuple[dict[str, dict[str, Any]], list[dict[str, Any]]]:
    ordered = sorted(
        (path.resolve() for path in paths if path.is_file()),
        key=lambda path: (path.stat().st_mtime_ns, path.name),
    )
    latest_terminal: dict[str, dict[str, Any]] = {}
    for path in ordered:
        for line_number, line in enumerate(
            path.read_text(encoding="utf-8").splitlines(),
            start=1,
        ):
            try:
                observation = json.loads(line)
            except json.JSONDecodeError:
                continue
            signature = observation.get("signature") or {}
            relative = str(signature.get("relative_path") or "")
            if not relative:
                continue
            observation["_source_jsonl"] = str(path)
            observation["_source_line"] = line_number
            status = observation.get("status")
            if status in {"success", "partial_success", "failed"}:
                latest_terminal[relative] = observation
    successes = {
        relative: observation
        for relative, observation in latest_terminal.items()
        if observation.get("status") == "success"
        and int(observation.get("success_items", 0)) == 12
    }
    rejected = [
        observation
        for relative, observation in latest_terminal.items()
        if relative not in successes
    ]
    return successes, rejected


def load_legacy_pairs(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            rows.append(json.loads(line))
    return rows


def v011_features_from_observation(
    observation: dict[str, Any],
) -> dict[str, Any]:
    features = deepcopy(observation.get("scoring_features") or {})
    uv_density = (
        (observation.get("v2_scoring_features") or {})
        .get("pigmentation", {})
        .get("uv_spots", {})
        .get("uv_spot_density_per_100k_px")
    )
    if not isinstance(uv_density, bool) and isinstance(uv_density, (int, float)):
        features.setdefault("uv_spots", {}).setdefault(
            "UV样色素范围", {}
        )["density"] = float(uv_density)
    return features


def build_paired_score_rows(
    observations: dict[str, dict[str, Any]],
    legacy_pairs: Iterable[dict[str, Any]],
    references: dict[str, list[float]],
) -> tuple[list[dict[str, Any]], list[dict[str, str]]]:
    prepared = prepare_references(references)
    paired: list[dict[str, Any]] = []
    unavailable: list[dict[str, str]] = []
    for pair in legacy_pairs:
        relative = str(pair["source_relative_path"])
        observation = observations.get(relative)
        if observation is None:
            unavailable.append({"relative_path": relative, "reason": "current_result_missing"})
            continue
        scores = legacy_dimension_scores_from_features(
            v011_features_from_observation(observation),
            prepared,
        )
        legacy = pair.get("legacy_scores") or {}
        for dimension in DIMENSION_IDS:
            current_score = scores.get(dimension)
            if current_score is None:
                unavailable.append({
                    "relative_path": relative,
                    "reason": f"current_{dimension}_unavailable",
                })
                continue
            target = legacy.get(dimension)
            if isinstance(target, bool) or not isinstance(target, (int, float)):
                unavailable.append({"relative_path": relative, "reason": f"legacy_{dimension}_missing"})
                continue
            paired.append({
                "relative_path": relative,
                "subject_id": pair.get("subject_id"),
                "split": pair.get("split"),
                "dimension_id": dimension,
                "current_score": float(current_score),
                "legacy_score": float(target),
            })
    return paired, unavailable


def _grade(value: float) -> int:
    return int(np.searchsorted(GRADE_THRESHOLDS, value, side="right"))


def fit_dimension_bridges(
    score_rows: Iterable[dict[str, Any]],
    *,
    minimum_validation: int = 150,
) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, Any]]:
    rows = [dict(row) for row in score_rows]
    mappings: dict[str, Any] = {}
    for dimension in sorted({str(row["dimension_id"]) for row in rows}):
        train = [
            row for row in rows
            if row["dimension_id"] == dimension and row["split"] == "train"
        ]
        mappings[dimension] = fit_isotonic(
            [row["current_score"] for row in train],
            [row["legacy_score"] for row in train],
        )
    for row in rows:
        mapped = apply_isotonic(
            mappings[str(row["dimension_id"])],
            float(row["current_score"]),
        )
        row["mapped_score"] = round(mapped, 8)
        row["raw_error"] = round(float(row["current_score"] - row["legacy_score"]), 8)
        row["mapped_error"] = round(mapped - float(row["legacy_score"]), 8)
        row["legacy_grade"] = _grade(float(row["legacy_score"]))
        row["current_grade"] = _grade(float(row["current_score"]))
        row["mapped_grade"] = _grade(mapped)
    by_dimension: dict[str, Any] = {}
    enough_samples = bool(mappings)
    promotion_allowed = bool(mappings)
    for dimension in mappings:
        splits: dict[str, Any] = {}
        for split in ("train", "validation"):
            subset = [
                row for row in rows
                if row["dimension_id"] == dimension and row["split"] == split
            ]
            if not subset:
                continue
            target = [row["legacy_score"] for row in subset]
            current = [row["current_score"] for row in subset]
            mapped = [row["mapped_score"] for row in subset]
            splits[split] = {
                "before_mapping": mapping_diagnostics(target, current),
                "after_mapping": mapping_diagnostics(target, mapped),
            }
        validation = splits.get("validation", {}).get("after_mapping", {})
        enough_samples &= int(validation.get("count", 0)) >= minimum_validation
        before = splits.get("validation", {}).get("before_mapping", {})
        promotion_allowed &= bool(
            int(validation.get("severe_reversal_count", 1)) == 0
            and float(validation.get("mean_absolute_error", float("inf")))
            <= float(before.get("mean_absolute_error", float("-inf")))
        )
        by_dimension[dimension] = splits
    return mappings, rows, {
        "status": "candidate" if enough_samples else "insufficient_samples",
        "promotion_gate": "pass" if enough_samples and promotion_allowed else "blocked",
        "minimum_validation_per_dimension": minimum_validation,
        "row_count": len(rows),
        "split_counts": dict(Counter(str(row["split"]) for row in rows)),
        "dimensions": by_dimension,
    }


__all__ = [
    "build_paired_score_rows",
    "fit_dimension_bridges",
    "load_legacy_pairs",
    "load_latest_observations",
    "v011_features_from_observation",
]
from __future__ import annotations

import numpy as np
import json
import os
from pathlib import Path

from src.scoring_bridge.fitting import (
    apply_isotonic,
    build_ecdf_profile,
    fit_isotonic,
    mapping_diagnostics,
)
from src.scoring_bridge.builder import (
    fit_dimension_bridges,
    load_latest_observations,
    v011_features_from_observation,
)


def test_isotonic_mapping_is_monotonic_and_reduces_training_error() -> None:
    source = [10.0, 20.0, 30.0, 40.0, 50.0]
    target = [18.0, 36.0, 32.0, 72.0, 85.0]

    mapping = fit_isotonic(source, target)
    predicted = [apply_isotonic(mapping, value) for value in source]

    assert np.all(np.diff(predicted) >= 0)
    assert np.mean(np.abs(np.asarray(predicted) - target)) < np.mean(
        np.abs(np.asarray(source) - target)
    )
    assert apply_isotonic(mapping, -100.0) == mapping["y"][0]
    assert apply_isotonic(mapping, 1000.0) == mapping["y"][-1]


def test_mapping_diagnostics_reports_no_severe_rank_reversal() -> None:
    target = [5.0, 25.0, 50.0, 75.0, 95.0]
    predicted = [10.0, 20.0, 55.0, 70.0, 90.0]

    diagnostics = mapping_diagnostics(target, predicted)

    assert diagnostics["spearman"] > 0.99
    assert diagnostics["pair_concordance"] == 1.0
    assert diagnostics["severe_reversal_count"] == 0
    assert diagnostics["absolute_error_p95"] >= diagnostics["absolute_error_p50"]


def test_ecdf_profile_preserves_zero_and_unavailable_rates() -> None:
    observations = [
        {"pores": {"density": {"value": 0.0}}},
        {"pores": {"density": {"value": 2.0}}},
        {"pores": {"density": {"value": None}}},
    ]

    profile = build_ecdf_profile(observations)
    value = profile["pores"]["density.value"]

    assert value["count"] == 2
    assert value["zero_rate"] == 0.5
    assert value["unevaluable_rate"] == 1 / 3
    assert value["p50"] == 1.0


def test_latest_success_observation_prefers_newer_jsonl(tmp_path: Path) -> None:
    older = tmp_path / "older.jsonl"
    newer = tmp_path / "newer.jsonl"
    older.write_text(json.dumps({
        "signature": {"relative_path": "a.jpg"},
        "status": "success",
        "success_items": 12,
        "scoring_features": {"version": 1},
    }) + "\n", encoding="utf-8")
    newer.write_text(json.dumps({
        "signature": {"relative_path": "a.jpg"},
        "status": "success",
        "success_items": 12,
        "scoring_features": {"version": 2},
    }) + "\n", encoding="utf-8")
    os.utime(older, ns=(1, 1))
    os.utime(newer, ns=(2, 2))

    observations, _ = load_latest_observations([older, newer])

    assert observations["a.jpg"]["scoring_features"]["version"] == 2


def test_latest_partial_supersedes_older_success_for_bridge(tmp_path: Path) -> None:
    older = tmp_path / "older.jsonl"
    newer = tmp_path / "newer.jsonl"
    older.write_text(json.dumps({
        "signature": {"relative_path": "a.jpg"},
        "status": "success",
        "success_items": 12,
        "scoring_features": {"version": 1},
    }) + "\n", encoding="utf-8")
    newer.write_text(json.dumps({
        "signature": {"relative_path": "a.jpg"},
        "status": "partial_success",
        "success_items": 2,
        "failure_category": "input_quality_reject",
    }) + "\n", encoding="utf-8")
    os.utime(older, ns=(1, 1))
    os.utime(newer, ns=(2, 2))

    observations, rejected = load_latest_observations([older, newer])

    assert "a.jpg" not in observations
    assert [row["signature"]["relative_path"] for row in rejected] == ["a.jpg"]


def test_dimension_bridge_fits_train_and_reports_validation() -> None:
    rows = []
    for dimension in ("visible_pores", "combined_pigmentation"):
        for index, (current, legacy) in enumerate(
            ((10, 15), (20, 28), (30, 40), (40, 52), (50, 65), (60, 75))
        ):
            rows.append({
                "relative_path": f"{dimension}-{index}.jpg",
                "dimension_id": dimension,
                "split": "train" if index < 4 else "validation",
                "current_score": float(current),
                "legacy_score": float(legacy),
            })

    mappings, evaluated, diagnostics = fit_dimension_bridges(
        rows,
        minimum_validation=2,
    )

    assert set(mappings) == {"visible_pores", "combined_pigmentation"}
    assert len(evaluated) == len(rows)
    assert diagnostics["status"] == "candidate"
    assert diagnostics["promotion_gate"] == "blocked"
    assert all(
        row["mapped_score"] >= 0.0 and row["mapped_score"] <= 100.0
        for row in evaluated
    )


def test_current_v2_uv_density_enriches_v011_feature_contract() -> None:
    observation = {
        "scoring_features": {"uv_spots": {"UV下更明显色素面积": {}}},
        "v2_scoring_features": {
            "pigmentation": {
                "uv_spots": {"uv_spot_density_per_100k_px": 12.5}
            }
        },
    }

    features = v011_features_from_observation(observation)

    assert features["uv_spots"]["UV样色素范围"]["density"] == 12.5
from __future__ import annotations

from pathlib import Path

from src.scoring_bridge.manifest import (
    LegacyCandidate,
    deduplicate_subjects,
    proportional_quotas,
    split_selection,
    subject_id_from_sample_name,
)
from src.scoring_bridge.legacy_scoring import (
    legacy_dimension_scores_from_features,
    legacy_scores_from_features,
    prepare_references,
)
from src.scoring_calibration.v011.registry import REGISTRY
from src.scoring_calibration.v011.scoring import score_observation


def _candidate(index: int) -> LegacyCandidate:
    batch = f"batch_{20 + index % 3:06d}"
    return LegacyCandidate(
        batch_name=batch,
        sample_name=f"{index}_1.jpg",
        subject_id=str(index),
        sample_dir=Path(batch) / f"{index}_1.jpg",
        rank_key=f"{index:064x}",
        scores=(float(index % 100),) * 4,
        score_decile=index % 10,
    )


def test_subject_id_removes_view_suffix_and_extension() -> None:
    assert subject_id_from_sample_name("481468_1.jpg") == "481468"
    assert subject_id_from_sample_name("clinic28-25.png") == "clinic28-25"


def test_proportional_quotas_use_largest_remainder_and_exact_total() -> None:
    quotas = proportional_quotas({"a": 1950, "b": 1950, "c": 556}, 200)
    assert sum(quotas.values()) == 200
    assert quotas["c"] < quotas["a"]


def test_subject_deduplication_keeps_one_view_deterministically() -> None:
    rows = (
        LegacyCandidate("batch", "1_0.jpg", "1", Path("a"), "b"),
        LegacyCandidate("batch", "1_1.jpg", "1", Path("b"), "a"),
    )
    assert deduplicate_subjects(rows)[0].sample_name == "1_1.jpg"


def test_split_selection_is_disjoint_and_exact() -> None:
    selection = split_selection(
        tuple(_candidate(index) for index in range(300)),
        primary_count=100,
        validation_count=20,
        reserve_count=20,
        seed="20260827",
    )
    train = {candidate.subject_id for candidate in selection.train}
    validation = {candidate.subject_id for candidate in selection.validation}
    reserve = {candidate.subject_id for candidate in selection.reserve}
    assert len(train) == 80
    assert len(validation) == 20
    assert len(reserve) == 20
    assert train.isdisjoint(validation | reserve)
    assert validation.isdisjoint(reserve)


def test_prepared_reference_fast_path_matches_official_v011_scorer() -> None:
    features: dict[str, dict] = {}
    references: dict[str, list[float]] = {}
    for dimension in REGISTRY:
        for group in dimension.groups:
            for metric in group.metrics:
                item, group_name, metric_name = metric.source.split(".")
                features.setdefault(item, {}).setdefault(group_name, {})[metric_name] = 1.0
                references[metric.id] = [0.0, 1.0, 2.0]
    official = score_observation(
        {
            "status": "success",
            "features": features,
            "input_quality_gate": {"status": "PASS", "reason_codes": []},
        },
        references,
    )
    expected = tuple(
        row["score"]
        for row in official["formal_dimension_scores"]
    )
    actual = legacy_scores_from_features(features, prepare_references(references))
    assert actual == expected


def test_missing_one_dimension_keeps_other_dimension_scores() -> None:
    features: dict[str, dict] = {}
    references: dict[str, list[float]] = {}
    for dimension in REGISTRY:
        for group in dimension.groups:
            for metric in group.metrics:
                item, group_name, metric_name = metric.source.split(".")
                features.setdefault(item, {}).setdefault(group_name, {})[
                    metric_name
                ] = 1.0
                references[metric.id] = [0.0, 1.0, 2.0]
    features.pop("pores")

    scores = legacy_dimension_scores_from_features(
        features,
        prepare_references(references),
    )

    assert scores["visible_pores"] is None
    assert scores["combined_pigmentation"] is not None
    assert scores["diffuse_redness"] is not None
    assert scores["surface_smoothness_decline"] is not None
