from __future__ import annotations

import hashlib
from collections import Counter, defaultdict
from dataclasses import dataclass
from typing import Mapping, Sequence


OUTER_FOLDS = 5
INNER_FOLDS = 4
GRADE_COUNT = 5


@dataclass(frozen=True, slots=True)
class FoldSample:
    subject_id: str
    relative_path: str
    stratum: str


@dataclass(frozen=True, slots=True)
class FoldAssignment:
    subject_id: str
    relative_path: str
    stratum: str
    outer_fold: int
    inner_fold_by_outer: Mapping[int, int | None]


@dataclass(frozen=True, slots=True)
class ConfirmationMember:
    subject_id: str
    grades: tuple[int, int, int, int]


@dataclass(frozen=True, slots=True)
class ConfirmationContractReport:
    subject_count: int
    per_dimension_grade_counts: tuple[Mapping[int, int], ...]


@dataclass(frozen=True, slots=True)
class ConfirmationContractError(ValueError):
    reason: str

    def __str__(self) -> str:
        return self.reason


def _stable_key(seed: str, *parts: str) -> str:
    return hashlib.sha256("\0".join((seed, *parts)).encode()).hexdigest()


def _round_robin(
    samples: Sequence[FoldSample],
    *,
    folds: int,
    seed: str,
    label: str,
) -> dict[str, int]:
    by_stratum: dict[str, list[FoldSample]] = defaultdict(list)
    for sample in samples:
        by_stratum[sample.stratum].append(sample)
    assigned: dict[str, int] = {}
    for stratum, rows in sorted(by_stratum.items()):
        ordered = sorted(
            rows,
            key=lambda row: _stable_key(seed, label, stratum, row.subject_id),
        )
        offset = int(_stable_key(seed, label, stratum)[:16], 16) % folds
        for index, row in enumerate(ordered):
            assigned[row.subject_id] = (offset + index) % folds
    return assigned


def build_nested_fold_assignments(
    samples: Sequence[FoldSample],
    *,
    seed: str,
) -> tuple[FoldAssignment, ...]:
    if len({sample.subject_id for sample in samples}) != len(samples):
        raise ValueError("fold samples contain duplicate subjects")
    outer = _round_robin(samples, folds=OUTER_FOLDS, seed=seed, label="outer")
    inner_maps: dict[int, dict[str, int]] = {}
    for outer_fold in range(OUTER_FOLDS):
        training = tuple(
            sample for sample in samples
            if outer[sample.subject_id] != outer_fold
        )
        inner_maps[outer_fold] = _round_robin(
            training,
            folds=INNER_FOLDS,
            seed=seed,
            label=f"inner-{outer_fold}",
        )
    return tuple(
        FoldAssignment(
            subject_id=sample.subject_id,
            relative_path=sample.relative_path,
            stratum=sample.stratum,
            outer_fold=outer[sample.subject_id],
            inner_fold_by_outer={
                outer_fold: inner_maps[outer_fold].get(sample.subject_id)
                for outer_fold in range(OUTER_FOLDS)
            },
        )
        for sample in sorted(samples, key=lambda item: item.relative_path)
    )


def validate_confirmation_contract(
    *,
    development_subjects: set[str],
    confirmation_members: Sequence[ConfirmationMember],
    minimum_subjects: int = 200,
    minimum_per_grade: int = 15,
) -> ConfirmationContractReport:
    subject_ids = [member.subject_id for member in confirmation_members]
    if len(set(subject_ids)) != len(subject_ids):
        raise ConfirmationContractError("confirmation contains duplicate subjects")
    if development_subjects.intersection(subject_ids):
        raise ConfirmationContractError("confirmation overlaps development subjects")
    if len(subject_ids) < minimum_subjects:
        raise ConfirmationContractError("confirmation subject count is insufficient")
    grade_counts: list[Mapping[int, int]] = []
    for dimension_index in range(4):
        counts = Counter(
            member.grades[dimension_index]
            for member in confirmation_members
        )
        if any(counts[grade] < minimum_per_grade for grade in range(GRADE_COUNT)):
            raise ConfirmationContractError(
                f"confirmation grade coverage is insufficient for dimension {dimension_index}"
            )
        grade_counts.append(dict(counts))
    return ConfirmationContractReport(
        subject_count=len(subject_ids),
        per_dimension_grade_counts=tuple(grade_counts),
    )


__all__ = [
    "ConfirmationContractError",
    "ConfirmationContractReport",
    "ConfirmationMember",
    "FoldAssignment",
    "FoldSample",
    "build_nested_fold_assignments",
    "validate_confirmation_contract",
]
from __future__ import annotations

import hashlib
import json
import os
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Final, Sequence

from pydantic import BaseModel, ConfigDict

from src.scoring_bridge.builder import load_latest_observations
from src.scoring_bridge.manifest import DIMENSION_IDS
from src.scoring_bridge.split_contract import (
    FoldSample,
    build_nested_fold_assignments,
)


GRADE_THRESHOLDS: Final = (20.0, 40.0, 60.0, 80.0)
POSE_FLAGS: Final = frozenset({
    "POSE_YAW",
    "POSE_PITCH",
    "POSE_ROLL",
    "EXTREME_POSE",
    "PARTIAL_FACE",
})


class ActivePair(BaseModel):
    model_config = ConfigDict(extra="ignore", frozen=True)

    subject_id: str
    source_relative_path: str
    batch_name: str
    legacy_scores: dict[str, float]


class ObservationSignature(BaseModel):
    model_config = ConfigDict(extra="ignore", frozen=True)

    relative_path: str


class ObservationQuality(BaseModel):
    model_config = ConfigDict(extra="ignore", frozen=True)

    status: str = "UNKNOWN"
    flags: tuple[str, ...] = ()


class FoldObservation(BaseModel):
    model_config = ConfigDict(extra="ignore", frozen=True)

    signature: ObservationSignature
    quality: ObservationQuality = ObservationQuality()


@dataclass(frozen=True, slots=True)
class FoldManifestReceipt:
    manifest_path: Path
    metadata_path: Path
    manifest_sha256: str


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _grade(value: float) -> int:
    return sum(value >= threshold for threshold in GRADE_THRESHOLDS)


def _atomic_write(path: Path, payload: bytes) -> None:
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_bytes(payload)
    os.replace(temporary, path)


def _stratum(pair: ActivePair, observation: FoldObservation) -> str:
    grades = "".join(
        str(_grade(pair.legacy_scores[dimension]))
        for dimension in DIMENSION_IDS
    )
    pose = (
        "pose_warning"
        if POSE_FLAGS.intersection(observation.quality.flags)
        else "pose_regular"
    )
    suffix = Path(pair.source_relative_path).suffix.lower() or "none"
    return "|".join((
        pair.batch_name,
        grades,
        observation.quality.status,
        suffix,
        pose,
    ))


def build_development_fold_manifest(
    *,
    active_pairs_path: Path,
    observation_paths: Sequence[Path],
    output_dir: Path,
    seed: str,
) -> FoldManifestReceipt:
    pairs = tuple(
        ActivePair.model_validate_json(line)
        for line in active_pairs_path.read_text(encoding="utf-8").splitlines()
        if line.strip()
    )
    observations, _ = load_latest_observations(observation_paths)
    samples: list[FoldSample] = []
    for pair in pairs:
        raw = observations.get(pair.source_relative_path)
        if raw is None:
            raise ValueError(
                f"active pair has no eligible observation: {pair.source_relative_path}"
            )
        observation = FoldObservation.model_validate(raw)
        samples.append(FoldSample(
            subject_id=pair.subject_id,
            relative_path=pair.source_relative_path,
            stratum=_stratum(pair, observation),
        ))
    assignments = build_nested_fold_assignments(tuple(samples), seed=seed)
    output_dir.mkdir(parents=True, exist_ok=True)
    manifest_path = output_dir / "development_nested_folds_1000.jsonl"
    manifest_payload = "".join(
        json.dumps(
            asdict(row),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ) + "\n"
        for row in assignments
    ).encode()
    _atomic_write(manifest_path, manifest_payload)
    manifest_sha = hashlib.sha256(manifest_payload).hexdigest()
    metadata_path = output_dir / "development_nested_folds_1000.metadata.json"
    metadata = {
        "schema_version": "aisia_scoring_nested_folds_v1",
        "seed": seed,
        "subject_count": len(assignments),
        "active_pairs_sha256": _sha(active_pairs_path),
        "observation_sources": [
            {"name": path.name, "sha256": _sha(path)}
            for path in sorted(observation_paths, key=lambda item: item.name)
        ],
        "manifest_sha256": manifest_sha,
    }
    _atomic_write(
        metadata_path,
        (json.dumps(metadata, ensure_ascii=False, indent=2) + "\n").encode(),
    )
    return FoldManifestReceipt(
        manifest_path=manifest_path,
        metadata_path=metadata_path,
        manifest_sha256=manifest_sha,
    )


